import type { Metadata, Viewport } from "next";
import { Geist, Geist_Mono } from "next/font/google";

import { Header } from "@/components/header";
import { Footer } from "@/components/footer";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

// ================= 1. EXPLICIT VIEWPORT OBJECT EXPORT =================
export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
};

// ================= 2. PRODUCTION READY SEO METADATA =================
export const metadata: Metadata = {
  title: "Dev innovative - Your Trusted Partner for Software Solutions",
  description: "Transform your business with Dev innovative, Specializing in software web, mobile app dev, blockchain, AI, & cloud solutions... Contact us",
  alternates: {
    canonical: "https://devinnovative.com/",
  },
  formatDetection: {
    telephone: false, // Prevents mobile browsers from automatically styling/linking numbers
  },
  robots: {
    index: true,
    follow: true,
    googleBot: {
      index: true,
      follow: true,
      "max-image-preview": "large",
      "max-snippet": -1,
      "max-video-preview": -1,
    },
  },
  
  // OpenGraph Meta (Facebook, LinkedIn sharing optimizations)
  openGraph: {
    locale: "en_US",
    type: "website",
    title: "Dev innovative - Your Trusted Partner for Software Solutions",
    description: "Transform your business with Dev innovative, Specializing in software web, mobile app dev, blockchain, AI, & cloud solutions... Contact us",
    url: "https://devinnovative.com/",
    siteName: "Dev iNN | Development Services Provider",
    images: [
      {
        url: "https://devinnovative.com/wp-content/uploads/2022/06/06-img.jpg",
        width: 1200,
        height: 630,
        alt: "Dev innovative Solutions Global Branding Asset",
      },
    ],
  },

  // Twitter Card Parameters
  twitter: {
    card: "summary_large_image",
    title: "Dev innovative - Your Trusted Partner for Software Solutions",
    description: "Transform your business with Dev innovative, Specializing in software web, mobile app dev, blockchain, AI, & cloud solutions... Contact us",
    images: ["https://devinnovative.com/wp-content/uploads/2022/06/06-img.jpg"],
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
      suppressHydrationWarning
    >
      <body className="min-h-full flex flex-col bg-white text-slate-900" suppressHydrationWarning>
        <Header />
        
        {/* Main layout grow wrapper prevents the footer from jumping on empty page contexts */}
        <main className="flex-1 w-full flex flex-col">
          {children}
        </main>
        
        <Footer />
      </body>
    </html>
  );
}